// type Topic = 'Bought' | 'Sold' | 'Create' | 'Completed'
// Publish,Buy,Sell,CompleteBonding
enum Topic {
  Publish = 'Create',
  Buy = 'Bought',
  Sell = 'Sold',
  CompleteBonding = 'Completed'
}
type RecivedTopic = 'Publish' | 'Buy' | 'Sell' | 'CompleteBonding'
type DisplayTopic = 'Created' | 'Bought' | 'Sold' | 'Completed'
const topicMap: Record<RecivedTopic, DisplayTopic> = {
  Publish: 'Created',
  Buy: 'Bought',
  Sell: 'Sold',
  CompleteBonding: 'Completed'
}

