export function useWsEvents() {
  const socketRef = useRef<any>(null)
  const { eventList, marqueePaused, setEventList, setLastThree, pushHomeAnimEvent } = useEventStore()
  // const [list, setList] = useState<any>([])
  const eventListRef = useRef<any>([])
  const marqueePausedRef = useRef<boolean>(false)
  const heartbeatIntervalRef = useRef<any>(null)

  useInterval({
    interval: 5 * 1000,
    callback: () => {
      //   console.log('🚀 ~ file: useWsEvents.ts:69 ~ connectWebSocket ~ socketRef:', socketRef.current)
      if (socketRef.current && socketRef.current.readyState === WebSocket.CLOSED) {
        connectWebSocket()
      }
    }
  })

  useEffect(() => {
    marqueePausedRef.current = marqueePaused
  }, [marqueePaused])

  const connectWebSocket = () => {
    try {
      if (socketRef.current) {
        socketRef.current.close()
      }

      // socketRef.current = new WebSocket('wss://ws.ifelse.io')
      socketRef.current = new WebSocket(`${envConfigs.pump_api.ws_domain}/api/v1/event`)
      // socketRef.current = new WebSocket('ws://47.237.137.65:8080/api/v1/event')

      socketRef.current.onopen = () => {
        console.log('🚀 ~ file: useWsEvents.ts:77 ~ connectWebSocket ~ onopen:')

        const subscibeMessage = JSON.stringify({
          subscribe: 'Publish,Buy,Sell,CompleteBonding'
        })
        socketRef.current.send(subscibeMessage)

        // 开始心跳
        heartbeatIntervalRef.current = setInterval(() => {
          if (socketRef.current.readyState === WebSocket.OPEN) {
            socketRef.current.send(JSON.stringify({ type: 'heartbeat' }))
          }
        }, 30000) // 每30秒发送一次心跳
      }
      // 接收消息
      socketRef.current.onmessage = (event: any) => {
        console.log('🚀 ~ file: useWsEvents.ts:92 ~ connectWebSocket ~ event:', event)
        if (event?.data) {
          try {
            const parseData = wrapEventData(JSON.parse(event?.data))
            const newList = [...eventListRef.current, parseData]
            if (newList.length > 40) {
              newList.shift()
            }
            eventListRef.current = [...newList]

            if (parseData.topic === 'Created') {
              pushHomeAnimEvent(parseData)
            }
          } catch (e) {
            console.log('🚀 ~ file: useWsEvents.ts:62 ~ useEffect ~ e:', e)
          }
        }
      }

      socketRef.current.onclose = () => {
        console.log('🚀 ~ file: useWsEvents.ts:108 ~ connectWebSocket ~ onclose:')
      }

      socketRef.current.onerror = (error: any) => {
        console.log('🚀 ~ file: useWsEvents.ts:112 ~ connectWebSocket ~ error:', error)
      }
    } catch (error) {
      console.log('🚀 ~ file: useWsEvents.ts:116 ~ connectWebSocket ~ error:', error)
    }
  }

  useEffect(() => {
    connectWebSocket()
    return () => {
      if (socketRef.current) {
        socketRef.current.close()
      }
      clearInterval(heartbeatIntervalRef.current)
    }
  }, [])

  useEffect(() => {
    if (eventListRef.current.length === 20 && eventList.length < 20) {
      setEventList(eventListRef.current)
    }
  }, [eventListRef.current])

  const marqueeTimerRef = useRef<any>(null)
  const handleStartMarqueePolling = () => {
    marqueeTimerRef.current = setInterval(() => {
      setEventList([...eventListRef.current.slice(-20)])
    }, 30000) // 每隔30秒更新一次，为了配合css3动画(滚动播放)
  }

  const handleStopMarqueePolling = () => {
    clearInterval(marqueeTimerRef.current)
    marqueeTimerRef.current = null
  }

  const lastThreeTimerRef = useRef<any>(null)
  const handleStartLastThreePolling = () => {
    lastThreeTimerRef.current = setInterval(() => {
      setLastThree([...eventListRef.current.slice(-3)])
    }, 4000) // 每隔4秒更新一次，为了配合css3动画(气泡)
  }

  const handleStopLastThreePolling = () => {
    clearInterval(lastThreeTimerRef.current)
    lastThreeTimerRef.current = null
  }

  // 模拟数据用
  // const sendMessage = (data: any) => {
  //   if (socketRef.current && socketRef.current.readyState === WebSocket.OPEN) {
  //     if (data) {
  //       socketRef.current.send(JSON.stringify(wrapEventData(data)))
  //     }
  //   } else {
  //     console.error('WebSocket is not open')
  //   }
  // }

  // 处理获取到的数据
  const wrapEventData = (data: any) => {
    return {
      id: uuidV4(),
      topic: topicMap[data.topic as RecivedTopic], // 类型， 买/卖/创建/完成
      account: data?.operator_address || data?.creator_address || '', // 创建地址或交易地址
      symbol: data?.token_symbol,
      amountSui: bnToAmount(data?.amount_sui, 9) || '', // 花费的SUI数量
      image: data?.image_url,
      date: timeFormat(new Date(Number(data?.timestamp || 0) * 1000), 'MDY'),
      timestamp: data?.timestamp,
      coin_type: extractStructTagFromType(data?.coin_type).full_address
    }
  }

  // 模拟推送用
  // const timerRef = useRef<any>(null)
  // useEffect(() => {
  //   timerRef.current = setInterval(() => {
  //     const index = Math.floor(Math.random() * 4)
  //     sendMessage(mockData[index])
  //   }, 2000)

  //   return () => {
  //     clearInterval(timerRef.current)
  //     timerRef.current = null
  //   }
  // }, [])

  useEffect(() => {
    handleStartMarqueePolling()
    handleStartLastThreePolling()

    return () => {
      handleStopMarqueePolling()
      handleStopLastThreePolling()
    }
  }, [])

  return {
    handleStartMarqueePolling,
    handleStopMarqueePolling,
    handleStartLastThreePolling,
    handleStopLastThreePolling
  }
}
