export default function Layout() {
  useTitle('Cetus Pump')
  const { isTerm, setIsTerm } = useWebConfigStore()
  const { eventList } = useEventStore()
  const { currentAccount } = useAccountStore()
  const { fetchAccountBalance } = useAccountBalance()
  const { fetchTokenPrices } = useTokenPrice()
  const { fetchGlobalConfig, globalConfig } = useGetGlobalConfig()
  useWsEvents()
  const { transactionModalVisible, transactionData, setTransactionModalVisible } = useTransactionStore()
  const { isOpenWalletModal, onWalletModal } = useAccountStore()
  const { isApp, windowWidth } = useWindowWidth()
  const { pathname } = useLocation()
  const { pumpSdk } = usePumpSDKStore()
  const { fetchFrontConfig } = useGetFrontConfig()

  const [language, setLanguage] = useState('EN')
  const [preferred, setFreferred] = useState('Suiscan')
  const [node, setNode] = useState('Suiscan')
  useEffect(() => {
    if (currentAccount?.address) {
      fetchAccountBalance(currentAccount.address)
    }
  }, [currentAccount?.address])

  useEffect(() => {
    fetchTokenPrices([SUI_TYPE_ARG])
    fetchGlobalConfig()
    //TODO 暂时写在pump index， 后期需要写在web index
    fetchFrontConfig()
  }, [])

  useInterval({
    interval: 30 * 1000,
    callback: () => {
      fetchTokenPrices([SUI_TYPE_ARG])

      if (!globalConfig) {
        fetchGlobalConfig()
      }
    }
  })

  // RPC 切换后，需要重新获取余额
  useEffect(() => {
    if (pumpSdk?.sdkOptions.fullRpcUrl) {
      fetchAccountBalance()
    }
  }, [pumpSdk?.sdkOptions.fullRpcUrl])

  const setting = {
    language: {
      options: ['EN English', 'CH 中文'],
      value: language,
      onValueChange: value => setLanguage(value)
    },
    preferred: {
      options: ['SuiVision', 'Suiscan'],
      value: preferred,
      onValueChange: value => setFreferred(value)
    },
    rpcNode: {
      options: ['Suiscan', 'SUIscan2'],
      value: node,
      onValueChange: value => setNode(value)
    }
  }
  const showScrollHeader = useMemo(() => {
    return !pathname.includes('home') && eventList.length > 0
  }, [pathname, eventList?.length])

  const showToTopIcon = useMemo(() => {
    return ['home', 'ranking', 'profile'].some(path => pathname.includes(path))
  }, [pathname])

  const [showScrollToTop, setShowScrollToTop] = useState(false)
  const hStackRef = useRef<HTMLDivElement>(null)

  const handleScroll = () => {
    if (hStackRef.current) {
      setShowScrollToTop(hStackRef.current.scrollTop > 100)
    }
  }

  const scrollToTop = () => {
    if (hStackRef.current) {
      hStackRef.current?.scrollTo({ top: 0, behavior: 'instant' })
    }
  }
  useEffect(() => {
    if (pathname) {
      scrollToTop()
    }
  }, [pathname])

  useEffect(() => {
    const hStack = hStackRef.current
    if (hStack) {
      hStack.addEventListener('scroll', handleScroll)
      return () => hStack.removeEventListener('scroll', handleScroll)
    }
  }, [])
  return (
    <>
      {showScrollHeader && !isApp && <ScrollHeader dataSource={eventList} />}
      <Box
        background="bg_primary"
        // minW={pathname.includes('home') || windowWidth < 1240 ? '100%' : '1240px'}
        h={showScrollHeader && !isApp ? 'calc(100vh - 60px)' : '100vh'}
        position="relative"
        width="100%"
      >
        <Header logo={{ image: Logo, url: '/home' }} menus={menuList} setting={setting} isCetusPump={true} />
        <Box
          as="div"
          pb={{
            base: '20px',
            lg: '60px'
          }}
          style={{
            width: '100%',
            position: 'relative',
            height: showScrollHeader && !isApp ? 'calc(100vh - 140px)' : isApp ? 'calc(100vh - 48px)' : 'calc(100vh - 80px)',
            overflowY: 'auto',
            overflowX: 'hidden'
            // overflowX: pathname.includes('home') ? 'hidden' : 'auto'
          }}
          ref={hStackRef}
        >
          <Suspense fallback={<Spinner size="32px" wrapStyle={{ bg: 'bg_primary' }} />}>
            {showScrollHeader && isApp && (
              <Box>
                <ScrollHeader dataSource={eventList} />
              </Box>
            )}
            <VStack w="100%">
              <Flex
                w="100%"
                maxW="1240px"
                p={{
                  base: '0 8px',
                  lg: '0 20px'
                }}
                justifyContent="center"
                zIndex="1"
              >
                <Outlet />
              </Flex>
            </VStack>
            {showScrollToTop && showToTopIcon && (
              <Block
                cursor="pointer"
                w="40px"
                h="40px"
                p="0"
                borderRadius="12px"
                zIndex="99"
                position="fixed"
                bottom="30px"
                right="20px"
                onClick={scrollToTop}
              >
                <Center w="100%" h="100%">
                  <Icon xlinkHref="#icon-icon_top1" onClick={scrollToTop} />
                </Center>
              </Block>
            )}
          </Suspense>
        </Box>
        <BgContent />
      </Box>
      {isOpenWalletModal && <WalletModal isOpen={isOpenWalletModal} onClose={() => onWalletModal(false)} />}

      {/* 交易弹窗 */}
      {transactionModalVisible && transactionData && (
        <TransactionModal
          isOpen={transactionModalVisible}
          onClose={() => {
            setTransactionModalVisible(false)
          }}
          {...transactionData}
        />
      )}
      {/* 用户第一次进入网站许可弹框 */}
      {!isTerm && <TermConditionsModal isOpen={!isTerm} onClose={() => setIsTerm(true)} />}
    </>
  )
}

