import useEventStore from '@/store/event'
import { Box, HStack } from '@chakra-ui/react'
import Marquee from 'react-fast-marquee'
import ScrollInfo from './common/ScrollInfo'
interface ScrollHeaderProps {
  dataSource: any[]
}

function ScrollHeader({ dataSource }: ScrollHeaderProps) {
  const { setMarqueePaused } = useEventStore()
  return (
    <Box
      w="100%"
      h="60px"
      bg="scroll_header_bg"
      p="8px 0px"
      overflow="hidden"
      whiteSpace="nowrap"
      onMouseEnter={() => setMarqueePaused(true)}
      onMouseLeave={() => setMarqueePaused(false)}
    >
      <Box bg="linear-gradient( 270deg, #005B99 0%, #480077 100%)" w="100%" h="2px" />
      <Marquee pauseOnHover speed={100}>
        <HStack gap="78px" h="40px" ml="78px" justify="flex-start">
          {dataSource?.map((item, index) => {
            return <ScrollInfo key={index} {...item} />
          })}
        </HStack>
      </Marquee>

      <Box bg="linear-gradient( 270deg, #005B99 0%, #480077 100%)" w="100%" h="2px" />
    </Box>
  )
}

export default ScrollHeader
